export const translate = (language, key, values = {}) => {
  const translations = catalog[key];
  const localeIndex = localeIndexes[language] ?? localeIndexes.English;
  const template = translations?.[localeIndex] ?? translations?.[0] ?? key;
  return template.replace(/\{(\w+)\}/g, (_, name) => values[name] ?? "");
};
